    public GameObject SpawnedInstance => spawnedInstance;

    public SpawnEntityCommand(GameObject prefab, Vector3 position, Quaternion rotation, Transform parent)
    {
        this.prefab = prefab;
        this.position = position;
        this.rotation = rotation;
        this.parent = parent;
        this.timestamp = Time.time;
    }

    public void Execute()
    {
        spawnedInstance = UnityEngine.Object.Instantiate(prefab, position, rotation, parent);
