    public float Mass;
    public float3 Velocity;
    public float3 AngularVelocity;
    public bool IsKinematic;
}

[UpdateInGroup(typeof(PhysicsSimulationGroup))]
[UpdateBefore(typeof(PhysicsSystemGroup))]
[BurstCompile]
public partial struct CustomPhysicsSystem : ISystem
{
    [BurstCompile]
    public void OnUpdate(ref SystemState state)
    {
        float deltaTime = SystemAPI.Time.DeltaTime;
        float3 gravity = new float3(0, -9.81f, 0);

        foreach (var (body, velocity, mass) in
            SystemAPI.Query<RefRW<PhysicsBody>, RefRW<PhysicsVelocity>, RefRO<PhysicsMass>>())
        {
            if (body.ValueRO.IsKinematic) continue;

            float3 currentVel = velocity.ValueRO.Linear;
            currentVel += gravity * deltaTime;
            currentVel *= math.max(0f, 1f - 0.01f * deltaTime);

            velocity.ValueRW.Linear = currentVel;
            body.ValueRW.Velocity = currentVel;
        }
    }
}

[BurstCompile]
public partial struct RaycastSystem : ISystem
{
    [BurstCompile]
    public void OnUpdate(ref SystemState state)
    {
        var physicsWorld = SystemAPI.GetSingleton<PhysicsWorldSingleton>();
        var collisionWorld = physicsWorld.CollisionWorld;

        foreach (var (transform, raycaster) in
            SystemAPI.Query<RefRO<LocalTransform>, RefRO<RaycasterData>>())
        {
            RaycastInput input = new RaycastInput
            {
                Start = transform.ValueRO.Position,
                End = transform.ValueRO.Position + raycaster.ValueRO.Direction * raycaster.ValueRO.MaxDistance,
                Filter = CollisionFilter.Default
            };

            if (collisionWorld.CastRay(input, out RaycastHit hit))
            {
                Debug.Log($"Hit entity: {hit.Entity} at distance {hit.Fraction}");
            }
        }
    }
}

