using Unity.Entities;
using Unity.Collections;
using Unity.Mathematics;
using Unity.Physics;
using Unity.Transforms;

public struct SimulationSnapshot : IDisposable
{
    public NativeArray<float3> Positions;
    public NativeArray<quaternion> Rotations;
    public NativeArray<float3> Velocities;
    public NativeArray<float3> AngularVelocities;
    public float Time;
    public uint Tick;

    public SimulationSnapshot(int capacity, Allocator allocator)
    {
        Positions = new NativeArray<float3>(capacity, allocator);
        Rotations = new NativeArray<quaternion>(capacity, allocator);
        Velocities = new NativeArray<float3>(capacity, allocator);
        AngularVelocities = new NativeArray<float3>(capacity, allocator);
        Time = 0f;
        Tick = 0;
    }

    public void Dispose()
    {
        if (Positions.IsCreated) Positions.Dispose();
        if (Rotations.IsCreated) Rotations.Dispose();
        if (Velocities.IsCreated) Velocities.Dispose();
        if (AngularVelocities.IsCreated) AngularVelocities.Dispose();
    }
}

public partial struct PhysicsStateSerializer : ISystem
{
    private NativeList<SimulationSnapshot> stateHistory;
    private const int MAX_HISTORY = 120;

    public void OnCreate(ref SystemState state)
    {
        stateHistory = new NativeList<SimulationSnapshot>(MAX_HISTORY, Allocator.Persistent);
    }

    [BurstCompile]
    public void OnUpdate(ref SystemState state)
    {
        var query = SystemAPI.QueryBuilder()
            .WithAll<LocalTransform, PhysicsVelocity>()
            .Build();

        var entities = query.ToEntityArray(Allocator.Temp);
        var snapshot = new SimulationSnapshot(entities.Length, Allocator.Persistent);

        for (int i = 0; i < entities.Length; i++)
        {
            var transform = SystemAPI.GetComponent<LocalTransform>(entities[i]);
            var velocity = SystemAPI.GetComponent<PhysicsVelocity>(entities[i]);

            snapshot.Positions[i] = transform.Position;
            snapshot.Rotations[i] = transform.Rotation;
            snapshot.Velocities[i] = velocity.Linear;
            snapshot.AngularVelocities[i] = velocity.Angular;
        }

        snapshot.Time = (float)SystemAPI.Time.ElapsedTime;
        snapshot.Tick = (uint)(SystemAPI.Time.ElapsedTime * 60f);

        stateHistory.Add(snapshot);

        while (stateHistory.Length > MAX_HISTORY)
        {
            stateHistory[0].Dispose();
            stateHistory.RemoveAt(0);
        }

        entities.Dispose();
    }

    public void OnDestroy(ref SystemState state)
    {
        foreach (var snapshot in stateHistory)
            snapshot.Dispose();
        stateHistory.Dispose();
    }

    public void RestoreState(uint targetTick, ref SystemState state)
    {
        for (int i = stateHistory.Length - 1; i >= 0; i--)
        {
            if (stateHistory[i].Tick == targetTick)
            {
                var query = SystemAPI.QueryBuilder()
                    .WithAll<LocalTransform, PhysicsVelocity>()
                    .Build();
                var entities = query.ToEntityArray(Allocator.Temp);

                for (int j = 0; j < entities.Length && j < stateHistory[i].Positions.Length; j++)
                {
                    var transform = SystemAPI.GetComponentRW<LocalTransform>(entities[j]);
                    var velocity = SystemAPI.GetComponentRW<PhysicsVelocity>(entities[j]);

                    transform.ValueRW.Position = stateHistory[i].Positions[j];
                    transform.ValueRW.Rotation = stateHistory[i].Rotations[j];
                    velocity.ValueRW.Linear = stateHistory[i].Velocities[j];
                    velocity.ValueRW.Angular = stateHistory[i].AngularVelocities[j];
                }

                entities.Dispose();
                break;
            }
        }
    }
}

public partial struct FixedTickSystem : ISystem
{
    private float accumulator;
    private const float FIXED_TIMESTEP = 1f / 60f;
    private uint currentTick;

    public void OnCreate(ref SystemState state)
    {
        accumulator = 0f;
        currentTick = 0;
    }

    public void OnUpdate(ref SystemState state)
    {
        float deltaTime = SystemAPI.Time.DeltaTime;
        accumulator += deltaTime;

        while (accumulator >= FIXED_TIMESTEP)
        {
            RunPhysicsStep(FIXED_TIMESTEP, currentTick);
            accumulator -= FIXED_TIMESTEP;
            currentTick++;
        }
    }

    void RunPhysicsStep(float dt, uint tick)
    {
    }
}
